/* Modèle de Merton : distribution des actifs, barrière de défaut, PD & spread */
(function () {
  var svg = document.getElementById("cr-chart");
  if (!svg) return;
  var R = 0.02;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }
  function ncdf(x){
    var k=1/(1+0.2316419*Math.abs(x));
    var d=0.3989423*Math.exp(-x*x/2);
    var p=d*k*(0.3193815+k*(-0.3565638+k*(1.781478+k*(-1.821256+k*1.330274))));
    return x>=0 ? 1-p : p;
  }

  function draw(){
    var lev=v("cr-lev")/100, sig=v("cr-vol")/100, T=Math.round(v("cr-t"));
    setT("cr-lev-o",(lev*100).toFixed(0)+"%"); setT("cr-vol-o",(sig*100).toFixed(0)+"%"); setT("cr-t-o",T.toFixed(0));
    var V=100, D=lev*100;
    var sq=sig*Math.sqrt(T);
    var d2=(Math.log(V/D)+(R-sig*sig/2)*T)/sq;
    var d1=d2+sq;
    var PD=ncdf(-d2), DD=d2;
    var E=V*ncdf(d1)-D*Math.exp(-R*T)*ncdf(d2);
    var B=V-E;
    var spread=-Math.log(B/(D*Math.exp(-R*T)))/T;
    setT("cr-dd",DD.toFixed(2));
    setT("cr-pd",(PD*100).toFixed(2)+"%");
    setT("cr-spread",(spread*10000).toFixed(0)+" bps");

    // distribution log-normale de V_T
    var W=520,H=260,L=16,Rm=16,T2=14,B2=34, pw=W-L-Rm, ph=H-T2-B2;
    var mu=Math.log(V)+(R-sig*sig/2)*T, s=sq;
    var xmax=Math.max(V*2.2, D*1.4);
    var xmin=0.001;
    function pdf(x){ if(x<=0) return 0; return Math.exp(-Math.pow(Math.log(x)-mu,2)/(2*s*s))/(x*s*Math.sqrt(2*Math.PI)); }
    var N=140, pts=[], ymax=0;
    for (var i=0;i<=N;i++){ var x=xmin+(xmax-xmin)*i/N; var y=pdf(x); pts.push({x:x,y:y}); if(y>ymax)ymax=y; }
    ymax*=1.12;
    function px(x){ return L + (x-xmin)/(xmax-xmin)*pw; }
    function py(y){ return T2 + (1-y/ymax)*ph; }

    function area(xa,xb,fill){
      var s2='M '+px(Math.max(xa,xmin)).toFixed(1)+','+py(0).toFixed(1)+' ';
      for (var i=0;i<=N;i++){ var x=pts[i].x; if(x<xa-1e-9)continue; if(x>xb+1e-9)break; s2+='L '+px(x).toFixed(1)+','+py(pts[i].y).toFixed(1)+' '; }
      s2+='L '+px(Math.min(xb,xmax)).toFixed(1)+','+py(0).toFixed(1)+' Z';
      return '<path d="'+s2+'" fill="'+fill+'"/>';
    }
    var g="";
    g+=area(xmin, D, "rgba(178,58,72,0.5)");     // défaut (crimson)
    g+=area(D, xmax, "rgba(22,112,106,0.35)");    // survie (teal)
    var poly=""; for (var j=0;j<pts.length;j++) poly+=px(pts[j].x).toFixed(1)+","+py(pts[j].y).toFixed(1)+" ";
    g+='<polyline points="'+poly.trim()+'" fill="none" stroke="var(--teal)" stroke-width="2.4"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+py(0)+'" x2="'+(L+pw)+'" y2="'+py(0)+'"/>';
    // barrière D
    g+='<line class="vline" x1="'+px(D)+'" y1="'+T2+'" x2="'+px(D)+'" y2="'+py(0)+'" stroke="var(--crimson)" stroke-width="1.6" stroke-dasharray="4 3"/>';
    g+='<text class="lab" x="'+px(D)+'" y="'+(T2+10)+'" text-anchor="middle" fill="var(--crimson)">D='+D.toFixed(0)+'</text>';
    // valeur initiale V
    g+='<line class="vline" x1="'+px(V)+'" y1="'+T2+'" x2="'+px(V)+'" y2="'+py(0)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="2 3"/>';
    g+='<text class="lab" x="'+px(V)+'" y="'+(T2+10)+'" text-anchor="middle">V₀='+V.toFixed(0)+'</text>';
    // ticks & légende
    g+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">0</text>';
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">'+xmax.toFixed(0)+'</text>';
    var xlab = al()==="en"?"asset value at maturity":(al()==="nl"?"activawaarde op vervaldag":"valeur des actifs à l'échéance");
    g+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    svg.innerHTML=g;
  }

  ["cr-lev","cr-vol","cr-t"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
